// FactVisits — visit fact for the PRIMARY matching dataset (adjacent_dp chronological pass; D-010, D-011, D-018).
// Source  : RepoRoot & "outputs\matching\candidate_visits.csv"  (generated by analysis/match_visits.py)
//           + unmatched reasons from outputs\matching\unmatched_intakes.csv and unmatched_outcomes.csv
// Grain   : visit_id (primary key, unique). ONE ROW PER visit candidate:
//             "Matched visit"                  172,547  (intake + outcome; LOS defined)
//             "Intake without matched outcome"   1,229  (outcome side blank; outcome_date null)
//             "Outcome without matched intake"   1,202  (intake side blank; intake_date null)
//           Total 174,978. NO rows are filtered here — unmatched rows are retained by design.
// Notes   : The 225 same-day time-reversed candidate pairs are NOT matched visits; their 450 events are
//           unmatched rows flagged same_day_reversed_candidate = true (D-018).
//           los_days = intake to final recorded outcome (not kennel time; foster placement unrecorded, D-019).
//           Exact duplicates were already excluded upstream, so no duplicate filter applies to this table.
let
    SourcePath = RepoRoot & "outputs\matching\candidate_visits.csv",
    Raw = Csv.Document(File.Contents(SourcePath), [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Promoted = Table.PromoteHeaders(Raw, [PromoteAllScalars = false]),

    ExpectedColumns = {
        "visit_id", "visit_status", "matching_method", "match_rule", "animal_id", "intake_event_id",
        "outcome_event_id", "intake_datetime", "outcome_datetime", "intake_date", "outcome_date", "los_days",
        "los_days_raw", "los_floored_to_zero", "los_band", "same_day_visit", "long_stay_365plus", "animal_type",
        "animal_type_mismatch", "intake_type", "intake_condition", "outcome_type", "outcome_subtype",
        "outcome_group", "outcome_status_provisional", "age_upon_intake_days", "age_band_intake", "breed_is_mix",
        "animal_intake_ordinal", "is_return_intake", "multiple_open_intakes", "n_eligible",
        "assignment_method_dependent", "intake_id_timestamp_conflict", "outcome_is_midnight",
        "outcome_time_is_date_only", "intake_age_dob_gap_days", "days_open_at_extract_end",
        "same_day_reversed_candidate", "candidate_partner_event_id"},
    Selected = Table.SelectColumns(Promoted, ExpectedColumns, MissingField.Error),
    BlankToNull = Table.TransformColumns(Selected, {}, each if _ = "" then null else _),

    ParseDate = (t as nullable text) as nullable date =>
        if t = null then null else Date.FromText(t, [Format = "yyyy-MM-dd", Culture = "en-US"]),
    ParseDateTime = (t as nullable text) as nullable datetime =>
        if t = null then null else DateTime.FromText(t, [Format = "yyyy-MM-dd HH:mm:ss", Culture = "en-US"]),
    ParseNumber = (t as nullable text) as nullable number =>
        if t = null then null else Number.FromText(t, "en-US"),
    ParseInt = (t as nullable text) as nullable number =>
        if t = null then null else Int64.From(Number.FromText(t, "en-US")),
    ParseFlag = (t as nullable text) as nullable logical =>
        if t = null then null else if t = "1" then true else if t = "0" then false
        else error Error.Record("InvalidFlag", "Expected 1/0 flag value", t),

    TextColumns = {
        "visit_id", "visit_status", "matching_method", "match_rule", "animal_id", "intake_event_id",
        "outcome_event_id", "los_band", "animal_type", "intake_type", "intake_condition", "outcome_type",
        "outcome_subtype", "outcome_group", "outcome_status_provisional", "age_band_intake",
        "candidate_partner_event_id"},
    TypedText = Table.TransformColumnTypes(BlankToNull, List.Transform(TextColumns, each {_, type text})),

    Typed = Table.TransformColumns(TypedText, {
        {"intake_datetime", ParseDateTime, type nullable datetime},
        {"outcome_datetime", ParseDateTime, type nullable datetime},
        {"intake_date", ParseDate, type nullable date},
        {"outcome_date", ParseDate, type nullable date},
        {"los_days", ParseNumber, type nullable number},
        {"los_days_raw", ParseNumber, type nullable number},
        {"age_upon_intake_days", ParseNumber, type nullable number},
        {"intake_age_dob_gap_days", ParseNumber, type nullable number},
        {"animal_intake_ordinal", ParseInt, Int64.Type},
        {"n_eligible", ParseInt, Int64.Type},
        {"days_open_at_extract_end", ParseInt, Int64.Type},
        {"los_floored_to_zero", ParseFlag, type nullable logical},
        {"same_day_visit", ParseFlag, type nullable logical},
        {"long_stay_365plus", ParseFlag, type nullable logical},
        {"animal_type_mismatch", ParseFlag, type nullable logical},
        {"breed_is_mix", ParseFlag, type nullable logical},
        {"is_return_intake", ParseFlag, type nullable logical},
        {"multiple_open_intakes", ParseFlag, type nullable logical},
        {"assignment_method_dependent", ParseFlag, type nullable logical},
        {"intake_id_timestamp_conflict", ParseFlag, type nullable logical},
        {"outcome_is_midnight", ParseFlag, type nullable logical},
        {"outcome_time_is_date_only", ParseFlag, type nullable logical},
        {"same_day_reversed_candidate", ParseFlag, type nullable logical}}),

    // Unmatched reasons (one row per unmatched visit_id in each file) -> left join on visit_id.
    ReadReasons = (relativePath as text) as table =>
        let
            R = Csv.Document(File.Contents(RepoRoot & relativePath),
                             [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
            P = Table.PromoteHeaders(R, [PromoteAllScalars = false]),
            S = Table.SelectColumns(P, {"visit_id", "unmatched_reason"}, MissingField.Error)
        in
            Table.TransformColumnTypes(S, {{"visit_id", type text}, {"unmatched_reason", type text}}),
    Reasons = Table.Combine({
        ReadReasons("outputs\matching\unmatched_intakes.csv"),
        ReadReasons("outputs\matching\unmatched_outcomes.csv")}),
    Joined = Table.NestedJoin(Typed, {"visit_id"}, Reasons, {"visit_id"}, "R", JoinKind.LeftOuter),
    WithReason = Table.ExpandTableColumn(Joined, "R", {"unmatched_reason"}, {"unmatched_reason"}),

    // Short, stable codes so DAX does not depend on long reason text.
    WithReasonCode = Table.AddColumn(WithReason, "unmatched_reason_code", each
        let r = [unmatched_reason] in
        if r = null then null
        else if Text.StartsWith(r, "Same-day time-reversed candidate") then "REVERSED_CANDIDATE"
        else if r = "Animal ID has no outcome records" then "NO_OUTCOME_RECORDS"
        else if Text.StartsWith(r, "No outcome recorded after this intake") then "NO_LATER_OUTCOME"
        else if Text.StartsWith(r, "Superseded") then "SUPERSEDED"
        else if Text.StartsWith(r, "Later outcomes already assigned") then "LATER_OUTCOMES_ASSIGNED"
        else if r = "Animal ID has no intake records" then "NO_INTAKE_RECORDS"
        else if Text.StartsWith(r, "No intake recorded before this outcome") then "NO_EARLIER_INTAKE"
        else if Text.StartsWith(r, "Preceding intake already closed") then "EXTRA_OUTCOME"
        else "OTHER", type nullable text),

    Keyed = Table.AddKey(WithReasonCode, {"visit_id"}, true)
in
    Keyed
